{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Dabrafenib, a structurally related kinase inhibitor with fluorophenyl and heteroaromatic motifs, has an absolute oral bioavailability of 94.5% measured by IV microtracer in patients, strongly supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Safinamide has an absolute oral bioavailability of 95% with absorption described as complete and not appreciably influenced by food, supporting high bioavailability for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Rufinamide, which shares a fluorobenzyl-heteroaryl motif with the query, shows good bioavailability of about 85%, especially when administered with food, directly supporting a high fed-state prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Alfuzosin under fed conditions has an absolute bioavailability of 49%, the lower end of the retrieved range but still well above the 20% threshold, supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Trovafloxacin has a mean absolute oral bioavailability of 87.6% in healthy subjects, providing additional transferable evidence that complex heteroaromatic oral drugs in this chemical space are highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Meloxicam has an absolute oral bioavailability of 89%, further supporting that the structural features shared with the query are compatible with high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Even ketanserin, which undergoes substantial first-pass metabolism, has an absolute oral bioavailability of 46.8%, confirming that the lowest retrieved values still exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable analogues show absolute oral bioavailability values well above 20%, ranging from about 47% to 95%, including under fed conditions; therefore the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule itself.",
    "The fed-state effect on the query is inferred from analogues rather than measured directly.",
    "Formulation-dependent variability in some analogues is not fully captured, but all reported values remain above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

